import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
)
​
// 判断闰年
func isLeap(y int) bool {
    return (y%400 == 0) || (y%4 == 0 && y%100 != 0)
}
​
// 每月天数
func daysInMonth(y, m int) int {
    d := []int{0,31,28,31,30,31,30,31,31,30,31,30,31}
    if m == 2 && isLeap(y) {
        return 29
    }
    return d[m]
}
​
// 加一分钟
func addOneMinute(t string) string {
    y,_ := strconv.Atoi(t[0:4])
    mo,_ := strconv.Atoi(t[4:6])
    d,_ := strconv.Atoi(t[6:8])
    h,_ := strconv.Atoi(t[8:10])
    mi,_ := strconv.Atoi(t[10:12])
​
    mi++
    if mi == 60 { // 进位到小时
        mi = 0
        h++
        if h == 24 { // 进位到天
            h = 0
            d++
            if d > daysInMonth(y, mo) { // 进位到月
                d = 1
                mo++
                if mo > 12 { // 进位到年
                    mo = 1
                    y++
                }
            }
        }
    }
    return fmt.Sprintf("%04d%02d%02d%02d%02d", y, mo, d, h, mi)
}
​
func main() {
    scanner := bufio.NewScanner(os.Stdin)
​
    // 查询时间范围
    scanner.Scan()
    startEnd := strings.Split(scanner.Text(), ",")
    start := startEnd[0]
    end := startEnd[1]
​
    // 压缩日志条数
    scanner.Scan()
    n,_ := strconv.Atoi(scanner.Text())
​
    // 存储压缩日志
    records := make([][]string, n)
    for i := 0; i < n; i++ {
        scanner.Scan()
        records[i] = strings.Split(scanner.Text(), ",")
    }
​
    // 存储查询到的有效区间
    var ans [][]string
​
    // 查询有交集的区间
    for _, rec := range records {
        currentStart := rec[0]
        currentEnd := rec[1]
        currentKpi := rec[2]
​
        // 升序, 后面不会存在交集
        if currentStart > end {
            break
        }
​
        // 判断当前记录是否与查询区间有交集
        if currentStart <= end && currentEnd >= start {
            s := currentStart
            e := currentEnd
            if currentStart < start {
                s = start
            }
            if currentEnd > end {
                e = end
            }
            ans = append(ans, []string{s, e, currentKpi})
        }
    }
​
    // 查询不到记录
    if len(ans) == 0 {
        fmt.Println(-1)
        return
    }
​
    // 输出查询结果
    first := true
    for _, r := range ans {
        cur := r[0]
        e := r[1]
        k := r[2]
​
        // 遍历区间的每一分钟
        for cur <= e {
            if !first {
                fmt.Println()
            }
            fmt.Printf("%s,%s", cur, k)
            first = false
            cur = addOneMinute(cur)
        }
    }
}
